import sys, json
import pandas as pd
import numpy as np

def to_float(x, nd=2):
    return round(float(x), nd)

def main():
    path = sys.argv[1]
    df = pd.read_csv(path)

    facts = []

    # ---------- TOTALS ----------
    tot_rev_tw = df['Revenue_TW'].sum(skipna=True)
    tot_rev_lw = df['Revenue_LW'].sum(skipna=True)
    tot_rev_ly = df['Revenue_LY'].sum(skipna=True) if df['Revenue_LY'].notna().any() else np.nan
    tot_units_tw = df['Units_TW'].sum(skipna=True)
    tot_units_lw = df['Units_LW'].sum(skipna=True)
    tot_orders_tw = df['Orders_TW'].sum(skipna=True)
    tot_orders_lw = df['Orders_LW'].sum(skipna=True)

    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "TW",
        "value": to_float(tot_rev_tw),
        "formula": "sum(Revenue_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "revenue", "period": "LW",
        "value": to_float(tot_rev_lw),
        "formula": "sum(Revenue_LW)"
    })
    if not np.isnan(tot_rev_ly):
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "LY",
            "value": to_float(tot_rev_ly),
            "formula": "sum(Revenue_LY)"
        })

    if tot_rev_lw and not np.isnan(tot_rev_lw) and tot_rev_lw != 0:
        wow = (tot_rev_tw - tot_rev_lw) / tot_rev_lw * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "WoW",
            "value": to_float(wow, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LW)) / sum(Revenue_LW) * 100"
        })

    if not np.isnan(tot_rev_ly) and tot_rev_ly != 0:
        yoy = (tot_rev_tw - tot_rev_ly) / tot_rev_ly * 100
        facts.append({
            "entity": "TOTAL", "metric": "revenue", "period": "YoY",
            "value": to_float(yoy, 1),
            "formula": "(sum(Revenue_TW) - sum(Revenue_LY)) / sum(Revenue_LY) * 100"
        })

    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "TW",
        "value": to_float(tot_units_tw),
        "formula": "sum(Units_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "units", "period": "LW",
        "value": to_float(tot_units_lw),
        "formula": "sum(Units_LW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "TW",
        "value": to_float(tot_orders_tw),
        "formula": "sum(Orders_TW)"
    })
    facts.append({
        "entity": "TOTAL", "metric": "orders", "period": "LW",
        "value": to_float(tot_orders_lw),
        "formula": "sum(Orders_LW)"
    })

    # ---------- TOP ENTITY BY RANK ----------
    if 'Rank' in df.columns and df['Rank'].notna().any():
        top_row = df.loc[df['Rank'].idxmin()]
        facts.append({
            "entity": top_row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(top_row['Revenue_TW']),
            "formula": "Revenue_TW for top ranked entity"
        })
        facts.append({
            "entity": top_row['Entity'], "metric": "revenue", "period": "LW",
            "value": to_float(top_row['Revenue_LW']) if pd.notna(top_row['Revenue_LW']) else None,
            "formula": "Revenue_LW for top ranked entity"
        })
        facts.append({
            "entity": top_row['Entity'], "metric": "share", "period": "TW",
            "value": to_float(top_row['Share_Pct'], 1) if pd.notna(top_row['Share_Pct']) else None,
            "formula": "Share_Pct for top ranked entity"
        })
        facts.append({
            "entity": top_row['Entity'], "metric": "rank", "period": "TW",
            "value": to_float(top_row['Rank'], 0),
            "formula": "Rank for top ranked entity (1 = highest revenue)"
        })

    # ---------- BIGGEST WoW MOVERS ----------
    wow_valid = df.dropna(subset=['WoW_Pct'])
    if not wow_valid.empty:
        gainer = wow_valid.loc[wow_valid['WoW_Pct'].idxmax()]
        decliner = wow_valid.loc[wow_valid['WoW_Pct'].idxmin()]
        facts.append({
            "entity": gainer['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(gainer['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (largest increase)"
        })
        facts.append({
            "entity": decliner['Entity'], "metric": "revenue", "period": "WoW",
            "value": to_float(decliner['WoW_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100 (largest decrease)"
        })

    # ---------- BIGGEST YoY MOVERS ----------
    yoy_valid = df.dropna(subset=['YoY_Pct'])
    if not yoy_valid.empty:
        gainer_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmax()]
        decliner_y = yoy_valid.loc[yoy_valid['YoY_Pct'].idxmin()]
        facts.append({
            "entity": gainer_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(gainer_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (largest increase)"
        })
        facts.append({
            "entity": decliner_y['Entity'], "metric": "revenue", "period": "YoY",
            "value": to_float(decliner_y['YoY_Pct'], 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100 (largest decrease)"
        })

    # ---------- TOP ENTITIES BY REVENUE (up to 3) ----------
    top_entities = df.dropna(subset=['Revenue_TW']).sort_values('Revenue_TW', ascending=False).head(3)
    for _, row in top_entities.iterrows():
        facts.append({
            "entity": row['Entity'], "metric": "revenue", "period": "TW",
            "value": to_float(row['Revenue_TW']),
            "formula": "Revenue_TW"
        })
        if pd.notna(row.get('Share_Pct')):
            facts.append({
                "entity": row['Entity'], "metric": "share", "period": "TW",
                "value": to_float(row['Share_Pct'], 1),
                "formula": "Revenue_TW / sum(Revenue_TW) * 100"
            })
        if pd.notna(row.get('Rank')):
            facts.append({
                "entity": row['Entity'], "metric": "rank", "period": "TW",
                "value": to_float(row['Rank'], 0),
                "formula": "Rank by Revenue_TW (1 = highest)"
            })

    # Clean None values, ensure python floats, cap to 25 facts
    clean_facts = []
    for f in facts:
        if f.get("value") is None:
            continue
        v = f["value"]
        if isinstance(v, (np.floating, np.integer)):
            v = float(v)
        f["value"] = v
        clean_facts.append(f)

    clean_facts = clean_facts[:25]

    print(json.dumps(clean_facts))

if __name__ == "__main__":
    main()
